import{_ as a,c as n,o as p,a5 as e}from"./chunks/framework.DorIfSpC.js";const g=JSON.parse('{"title":"快了兩倍多，然後我發現自己量錯了四次","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/project/minimax-h3-8step-acceleration"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/project/minimax-h3-8step-acceleration"}],["meta",{"property":"og:title","content":"快了兩倍多，然後我發現自己量錯了四次 | 星智未來"}],["meta",{"name":"twitter:title","content":"快了兩倍多，然後我發現自己量錯了四次 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"快了兩倍多，然後我發現自己量錯了四次\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/project/minimax-h3-8step-acceleration\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/project/minimax-h3-8step-acceleration\\"}}"]]},"headers":[],"relativePath":"project/minimax-h3-8step-acceleration.md","filePath":"project/minimax-h3-8step-acceleration.md","lastUpdated":1790609528000}'),t={name:"project/minimax-h3-8step-acceleration.md"};function i(o,s,l,r,d,c){return p(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="快了兩倍多-然後我發現自己量錯了四次" tabindex="-1">快了兩倍多，然後我發現自己量錯了四次 <a class="header-anchor" href="#快了兩倍多-然後我發現自己量錯了四次" aria-label="Permalink to &quot;快了兩倍多，然後我發現自己量錯了四次&quot;">​</a></h1><blockquote><p>MiniMax H3 的 8 步加速實測、兩個文件上查不到的坑，和四次量錯的紀錄</p></blockquote><p><strong>作者</strong>：Ray <strong>日期</strong>：2026 年 9 月 2 日（9 月 4 日補上大動態測試）</p><hr><p>8 月底，MiniMax H3 多了一個官方的加速方案：alibaba-pai 放出 <strong>PDD 蒸餾 LoRA</strong>，而且有 Ref2VA 專屬檔——20 步變 8 步。</p><p>我在 <a href="https://runpod.io?ref=s3bs0r0v" target="_blank" rel="noreferrer">RunPod</a> 上自架 H3 拍一部連載短劇，一集 22 顆鏡頭，全部 20 步跑要四個多小時。如果這東西是真的，那是一個晚上跟兩個晚上的差別。</p><p>我花了一個晚上把它接起來、量了兩組對照。</p><p><strong>結論是值得接。但那個晚上真正花掉時間的不是接線，是搞清楚我量到的數字算不算數。</strong></p><hr><h2 id="先講結果" tabindex="-1">先講結果 <a class="header-anchor" href="#先講結果" aria-label="Permalink to &quot;先講結果&quot;">​</a></h2><p>同一個鏡頭、同一顆種子、同一組參考圖，只換取樣路徑。兩次獨立量測：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                影格     20 步        8 步        比值</span></span>
<span class="line"><span>對話鏡頭         192    683.87 s    262.09 s    2.61×</span></span>
<span class="line"><span>大動態鏡頭       141    203.06 s     95.21 s    2.13×</span></span></code></pre></div><p><strong>2.1 到 2.6 倍。</strong></p><p>⚠️ 注意兩場次的<strong>絕對秒數差很多</strong>（20 步每影格 3.56 vs 1.44 秒）—— 那是換了 pod、換了卡。<strong>只有同場次的比值可以外推，跨場次的秒數不能比。</strong> 我後來就是在這裡摔了一跤，寫在下面。</p><p>一集 22 顆鏡頭：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>全 20 步   ≈ 4.2 小時</span></span>
<span class="line"><span>全  8 步   ≈ 1.6 小時</span></span></code></pre></div><hr><h2 id="接線-不是「加一個-lora」-是換一條取樣路徑" tabindex="-1">接線：不是「加一個 LoRA」，是換一條取樣路徑 <a class="header-anchor" href="#接線-不是「加一個-lora」-是換一條取樣路徑" aria-label="Permalink to &quot;接線：不是「加一個 LoRA」，是換一條取樣路徑&quot;">​</a></h2><p>這是我一開始理解錯的地方。我以為就是掛個 LoRA 節點，實際上<strong>取樣器和 sigma 的來源都要換掉</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原本</span></span>
<span class="line"><span>  載入擴散模型 ──────────────────────► 基礎引導器</span></span>
<span class="line"><span>  BasicScheduler（simple / 20 步）───► SamplerCustomAdvanced 的 Sigma 值</span></span>
<span class="line"><span>  K採樣器選擇 = res_multistep</span></span>
<span class="line"><span></span></span>
<span class="line"><span>改成</span></span>
<span class="line"><span>  載入擴散模型 ─► ModelSamplingMiniMaxH3 ─► MiniMax H3 PDD Acc LoRA (Apply)</span></span>
<span class="line"><span>                        (12.0 / 3.0)              │</span></span>
<span class="line"><span>                                    ┌── model ────┤</span></span>
<span class="line"><span>                                    ▼             └── sigmas ──┐</span></span>
<span class="line"><span>                             基礎引導器                         ▼</span></span>
<span class="line"><span>                                                 SamplerCustomAdvanced 的 Sigma 值</span></span>
<span class="line"><span>  K採樣器選擇 = euler</span></span>
<span class="line"><span>  ⛔ BasicScheduler 整個旁路掉</span></span></code></pre></div><p>⭐ <strong>sigmas 要接 Apply 節點的輸出，不是 BasicScheduler。</strong> 那組 sigma 是訓練時的區塊邊界，不是一般的排程曲線。<code>12.0 / 3.0</code> 那兩個數字也要照抄，官方文件寫的是 &quot;exactly&quot;。</p><p>節點包裡附了 <code>example_workflows/</code>，我本來想直接載——<strong>但它們在新版 ComfyUI 打不開</strong>。JSON 裡寫的是舊節點名 <code>MiniMaxH3SigmaShift</code>，現在改叫 <code>ModelSamplingMiniMaxH3</code>。自己接反而比較快。</p><p>⭐ 順帶一個讓人安心的設計：這個節點包有 <code>on_off_grid = error</code>。**接錯會直接報錯，不會默默產出垃圾。**所以可以放心接，錯了它會講。</p><hr><h2 id="坑一-節點裝好了-搜不到" tabindex="-1">坑一：節點裝好了，搜不到 <a class="header-anchor" href="#坑一-節點裝好了-搜不到" aria-label="Permalink to &quot;坑一：節點裝好了，搜不到&quot;">​</a></h2><p><code>git clone</code> 到 <code>custom_nodes/</code> 之後，搜尋框打節點名稱，<strong>「沒有結果」</strong>。</p><p>三個原因疊在一起，每一個單獨看都很蠢，但疊起來會讓你懷疑是不是裝壞了：</p><p><strong>一、ComfyUI 只在啟動時掃描 <code>custom_nodes/</code>。</strong> clone 完不會自己載入，要重啟。</p><p><strong>二、要用「顯示名稱」搜，不是 class 名稱。</strong> 打完整的 <code>MiniMaxH3PDDAccApply</code> 找不到，打 <code>pdd</code> 才會跳出來——因為節點包定義了 <code>NODE_DISPLAY_NAME_MAPPINGS</code>，搜尋比對的是顯示名。</p><p><strong>三、另一個必要的節點根本不在這個包裡。</strong> <code>ModelSamplingMiniMaxH3</code> 是 ComfyUI 內建的，標籤是 <code>Comfy</code>。所以搜 <code>pdd</code> 永遠找不到它，要搜 <code>shift</code>。</p><p>我在第三點上卡了一陣子，因為官方範例的 JSON 用的是舊名，而我照著那個名字去搜。</p><hr><h2 id="坑二-pdd-file-下拉是空的——而檔案明明就在" tabindex="-1">坑二：<code>pdd_file</code> 下拉是空的——而檔案明明就在 <a class="header-anchor" href="#坑二-pdd-file-下拉是空的——而檔案明明就在" aria-label="Permalink to &quot;坑二：\`pdd_file\` 下拉是空的——而檔案明明就在&quot;">​</a></h2><p>這個花最久，而且<strong>症狀完全誤導人</strong>。</p><p>節點出現了，LoRA 下載完了，<code>ls</code> 看得到 1.66 GB 躺在 <code>/workspace/ComfyUI/models/pdd_acc/</code>。但下拉選單是空的，欄位顯示 <code>undefined</code>。重啟沒用，硬重新整理沒用。</p><p>我花了一段時間在快取和權限上繞。然後停下來，<strong>直接問 server</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8188/object_info/MiniMaxH3PDDAccApply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import sys,json; d=json.load(sys.stdin); </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">print(d[&#39;MiniMaxH3PDDAccApply&#39;][&#39;input&#39;][&#39;required&#39;][&#39;pdd_file&#39;][0])&quot;</span></span></code></pre></div><p>回傳 <code>[]</code>。<strong>不是前端沒更新，是 server 真的看不到那個檔案。</strong></p><p>那就換一個問題：它到底在哪裡找？</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aux</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[m]ain.py&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># /opt/venv/bin/python3 /ComfyUI/main.py ... --extra-model-paths-config /ComfyUI/extra_model_paths.yaml</span></span></code></pre></div><p><strong>ComfyUI 根本不是跑在 <code>/workspace/ComfyUI</code>，是跑在 <code>/ComfyUI</code>。</strong></p><p>RunPod 這類範本的設計是：程式放在容器的 <code>/ComfyUI</code>，模型放在持久磁碟 <code>/workspace/ComfyUI/models</code>，靠 <code>extra_model_paths.yaml</code> 掛過去。標準的資料夾（checkpoints、loras、vae、diffusion_models）全都沒問題——<strong>所以你不會懷疑到這裡。</strong></p><p>但這個節點包新增了一種資料夾類型，而它是這樣寫的：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">_pdd_dir </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os.path.join(folder_paths.models_dir, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pdd_acc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># = /ComfyUI/models/pdd_acc</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">folder_paths.add_model_folder_path(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pdd_acc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, _pdd_dir, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">is_default</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>**它繞過了 yaml，直接用 <code>models_dir</code>。**所以它去 <code>/ComfyUI/models/pdd_acc</code> 找，而那裡是空的。</p><p>修法是一行 symlink：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /ComfyUI/models/pdd_acc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /workspace/ComfyUI/models/pdd_acc/minimax_h3_ref2va_pdd_acc_8step_comfyui.safetensors</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       /ComfyUI/models/pdd_acc/</span></span></code></pre></div><p>⚠️ <code>/ComfyUI</code> 在容器的暫存檔案系統上，<strong>關機就沒了——這行每次開機都要重做。</strong></p><p>⭐ 可以推廣的一條：**任何「自訂節點自己新增一種模型資料夾」的套件，在這類範本上都會踩到同一個坑。**症狀一律是「節點有出現、下拉是空的」，而那個症狀會讓你往快取和重啟的方向找很久。</p><p><strong>下次遇到，第一件事是 <code>ps aux | grep main.py</code>，看它到底跑在哪。</strong></p><hr><h2 id="我量錯的第一次和第二次" tabindex="-1">我量錯的第一次和第二次 <a class="header-anchor" href="#我量錯的第一次和第二次" aria-label="Permalink to &quot;我量錯的第一次和第二次&quot;">​</a></h2><p>接起來只花了那晚的前三分之一。剩下的時間全部花在「這個數字算不算數」。</p><h3 id="第一次-第一次跑的數字不能用" tabindex="-1">第一次：第一次跑的數字不能用 <a class="header-anchor" href="#第一次-第一次跑的數字不能用" aria-label="Permalink to &quot;第一次：第一次跑的數字不能用&quot;">​</a></h3><p>第一次量，20 步是 <strong>682.63 秒</strong>。我記成基準，算出加速比 2.57 倍，還挺得意。</p><p>然後我又跑了一次一模一樣的設定：<strong>510.74 秒。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>20 步  第一次   682.63s   ← 含模型首次載入</span></span>
<span class="line"><span>20 步  第二次   510.74s   ← 穩態</span></span>
<span class="line"><span>差               171.89s   ≈ 第一次的 25%</span></span></code></pre></div><p>這個錯有一個很討厭的性質：<strong>它是系統性偏誤，不是隨機誤差。</strong></p><p>你一定是先跑基準版、再接線、再跑加速版。所以<strong>被首次載入拖累的永遠是基準版</strong>，加速看起來永遠比實際好。如果沒發現，我會對外宣稱一個高估的數字。</p><p>而且我第一次量加速版時犯了同一個錯——那次含了 PDD LoRA 的首次載入，所以偏高。上面那組 192 影格的數字，是兩邊都跑到第二次之後才記的。</p><blockquote><p><strong>要比對任何設定，兩邊都跑到穩態再記數字。</strong></p></blockquote><h3 id="第二次-我下了一個站不住的畫質結論" tabindex="-1">第二次：我下了一個站不住的畫質結論 <a class="header-anchor" href="#第二次-我下了一個站不住的畫質結論" aria-label="Permalink to &quot;第二次：我下了一個站不住的畫質結論&quot;">​</a></h3><p>速度確定之後，我開始比畫質。抽同樣六個時間點的臉部特寫，兩版並排，寫下：</p><blockquote><p>8 步的皮膚明顯更平滑、蠟感重，毛孔與細紋少很多；眉毛變得又黑又硬，像畫上去的。</p></blockquote><p><strong>那個結論我收回了。</strong></p><p>因為 8 步版的<strong>走位變了</strong>：同一顆種子，換一條取樣路徑，人物的位置和景別就不一樣，8 步那版的臉在畫面裡大得多。為了並排比較，我把 20 步的小臉放大、8 步的大臉縮小——</p><p><strong>那個縮放本身就會製造「一個糊、一個平滑」的假象。</strong></p><p>我拿著一組被自己的前處理污染的圖，寫了一段看起來很專業的觀察。直到我把兩支<strong>原始影片</strong>並排給人看，得到的回答是：</p><blockquote><p>其實我看不大出來差別。</p></blockquote><p><strong>在沒有乾淨對照的情況下，直接看原片的判斷比我的裁切比對可信。</strong></p><p>要真的測畫質，得拿到景別相同的兩版。但同種子在不同取樣路徑下走位就是會變——<strong>所以這個對照可能根本做不出來。</strong></p><p>與其追一個做不出來的對照，不如直接用，出問題再說。</p><hr><h2 id="走位會不會變-看鏡頭的自由度" tabindex="-1">走位會不會變？看鏡頭的自由度 <a class="header-anchor" href="#走位會不會變-看鏡頭的自由度" aria-label="Permalink to &quot;走位會不會變？看鏡頭的自由度&quot;">​</a></h2><p>前兩支測試裡，換取樣路徑之後<strong>構圖與走位都跑掉了</strong>：一支景別變寬、人變小， 另一支角色多做了一個拱手的動作、鏡頭更近。</p><p>我當時寫下「同種子也一定會變」。<strong>9 月 4 日那支大動態測試推翻了它。</strong></p><p>那一支兩排逐格對得上——蹲、起身、舉臂、跳、髮飛、落地，時間點與姿勢都一致。</p><p>差別在<strong>鏡頭的自由度</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>會跑掉    雙人、有對白、機位與走位都沒寫死</span></span>
<span class="line"><span>不會跑    固定機位 ＋ 單一主體 ＋ 腳不移動 ＋ 每一拍都有明確時間戳</span></span></code></pre></div><p>大動態那支的提示詞把這些全部寫死了，包括一句 「the horizon line stays at exactly the same height in the frame from the first frame to the last」——用<strong>畫面裡的參照物</strong>去釘鏡頭，比寫 <code>static camera</code> 有效得多。</p><p><strong>所以這不是加速的代價，是提示詞約束不夠的代價。</strong></p><p>實務上仍然建議：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>⭐ 決定用幾步之後就固定，不要中途換</span></span>
<span class="line"><span>⭐ 想讓兩版可比，就把機位、主體位置、每一拍的時間戳全部寫死</span></span></code></pre></div><hr><h2 id="我原本最擔心的事沒有發生" tabindex="-1">我原本最擔心的事沒有發生 <a class="header-anchor" href="#我原本最擔心的事沒有發生" aria-label="Permalink to &quot;我原本最擔心的事沒有發生&quot;">​</a></h2><p>在跑之前，我最怕的不是畫質，是<strong>表演</strong>。</p><p>我之前實測過一次：同一份精確到 0.1 秒、有九個節拍的表情腳本，跑 226 影格全中，跑 362 影格<strong>全部跳過</strong>——臉從平靜直接跳到大笑，中間的微表情一格都沒有。</p><p>蒸餾把 20 步砍成 8 步，看起來就是同一類的風險：<strong>細微的臉部運動會不會被一起磨掉？</strong></p><p>所以我特別設計了一顆測試鏡頭，要的是「真心的笑」——眼睛先笑（下眼瞼上推、眼尾細紋），嘴角<strong>半秒之後</strong>才跟上。那個順序寫錯就變成社交假笑，是這類戲最挑剔的動作。</p><p>兩版跑出來：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✅ 笑容有出現     兩版同一個時間點都是閉唇的溫和微笑</span></span>
<span class="line"><span>✅ 眼睛有瞇起     兩版後段都看得到下眼瞼上推</span></span>
<span class="line"><span>✅ 臉不是死的     跟 362 影格那次完全不同</span></span></code></pre></div><p><strong>8 步做得到表情。</strong></p><p>⚪ 至於「眼睛先、嘴角後」那個順序有沒有精確執行——我測了兩版都沒有乾淨成立，但那是<strong>我的分鏡設計問題</strong>（鞠躬的動作把轉變遮住了），不是步數的問題。那是另一篇的事。</p><hr><h2 id="_9-4-補測-大動態" tabindex="-1">9/4 補測：大動態 <a class="header-anchor" href="#_9-4-補測-大動態" aria-label="Permalink to &quot;9/4 補測：大動態&quot;">​</a></h2><p>文章發出去之後，FB 社團有人留言：</p><blockquote><p>測一下大動態，看看影像會不會劣化。</p></blockquote><p><strong>這是我測不出來的那一塊，而他提的方法正好繞過我的困難。</strong></p><p>我前面比畫質失敗，是因為兩版走位不同、我為了並排把不同景別的臉縮放對齊， 結果製造了假的差異。<strong>大動態不用比紋理，是找瑕疵</strong>——拖影、閃爍、細節崩解。 那些東西不需要對齊構圖也看得出來。</p><p>於是我寫了一份規格書，開拍前就先把判定標準定死：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主體      一個人，沙灘上的排球扣殺，8 秒壓縮成 5.9 秒</span></span>
<span class="line"><span>機位      固定，不搖不推，腳不移動 ——【把取樣路徑的自由度壓下來】</span></span>
<span class="line"><span>觀察點    ① 齊下巴的鮑伯頭在空中會不會黏成一團</span></span>
<span class="line"><span>          ② 落地揚起的沙粒是顆粒還是糊塊</span></span>
<span class="line"><span>          ③ 影格間閃爍</span></span>
<span class="line"><span>判定      原始檔並排、原尺寸、禁止縮放</span></span>
<span class="line"><span>          先做完畫質判定，再去看時間數字</span></span></code></pre></div><p>第三條是為了防我自己——<strong>「省了七分鐘」這個念頭會污染畫質判斷。</strong></p><h3 id="結果-看不出差別" tabindex="-1">結果：看不出差別 <a class="header-anchor" href="#結果-看不出差別" aria-label="Permalink to &quot;結果：看不出差別&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>141 影格，同一顆種子，同一組參考圖，同一個 pod</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  20 步   203.06 s</span></span>
<span class="line"><span>   8 步    95.21 s      快 2.13 倍</span></span>
<span class="line"><span></span></span>
<span class="line"><span>髮絲（最劇烈那一格）   兩邊都是一根一根分明，飛散的細毛都在</span></span>
<span class="line"><span>沙粒                   顆粒密度與噴濺範圍幾乎一樣，都是顆粒不是糊塊</span></span>
<span class="line"><span>皮膚 / 拖影 / 閃爍     看不出差別</span></span></code></pre></div><p><strong>8 步在大動態下沒有可辨的劣化。</strong></p><p>⚠️ 誠實的但書：這是<strong>一顆鏡頭</strong>，而且規格書要求的「原尺寸並排 ＋ 找沒參與的人盲看」 我只做了一半。它不是統計，是一個資料點。</p><hr><h2 id="我量錯的第三次和第四次" tabindex="-1">我量錯的第三次和第四次 <a class="header-anchor" href="#我量錯的第三次和第四次" aria-label="Permalink to &quot;我量錯的第三次和第四次&quot;">​</a></h2><p>大動態那一輪，我又摔了兩跤，而且都是同一個病的變形。</p><h3 id="第三次-跨-pod-比較" tabindex="-1">第三次：跨 pod 比較 <a class="header-anchor" href="#第三次-跨-pod-比較" aria-label="Permalink to &quot;第三次：跨 pod 比較&quot;">​</a></h3><p>大動態那支 8 步跑出 95.21 秒。我拿它去除前一支測試的 20 步（510.74 秒）， 算出「<strong>5.4 倍</strong>」，還跟人說我先前發表的 2.6 倍低估了、先別引用。</p><p><strong>那兩支不同鏡頭、不同 pod。</strong></p><p>同樣是 20 步、同樣 141 影格，一場次是 510.74 秒，另一場次是 203.06 秒—— <strong>差 2.5 倍</strong>。中間換過機器。</p><blockquote><p><strong>跨場次的絕對秒數沒有意義，只有同場次的比值可以外推。</strong></p></blockquote><p>我在這篇的前半親手寫了「要比對任何設定，兩邊都跑到穩態再記數字」， 然後在下一輪違反了它的推論版本：<strong>兩邊還得是同一台機器。</strong></p><h3 id="第四次-叫人不要用一個其實是對的數字" tabindex="-1">第四次：叫人不要用一個其實是對的數字 <a class="header-anchor" href="#第四次-叫人不要用一個其實是對的數字" aria-label="Permalink to &quot;第四次：叫人不要用一個其實是對的數字&quot;">​</a></h3><p>因為算出 5.4 倍，我判定已發表的 2.6 倍是錯的，要 Ray 先別對外引用。</p><p><strong>2.6 倍是同場次量的，一直都站得住。</strong> 錯的是我拿來質疑它的那個數字。</p><p>補測之後兩次獨立量測是 2.13 倍和 2.61 倍——<strong>2.1 到 2.6 倍</strong>， 彼此印證，而且原本那個數字落在範圍內。</p><hr><h2 id="所以" tabindex="-1">所以 <a class="header-anchor" href="#所以" aria-label="Permalink to &quot;所以&quot;">​</a></h2><p><strong>接起來的成本</strong>：一個晚上，其中三分之二花在確認數字。文件上查不到的坑有兩個，這篇都寫了。</p><p><strong>買到的東西</strong>：一集從 4.2 小時變 1.6 小時。</p><p><strong>我的用法</strong>：預設全部 8 步。**看不出差別，就不要為它付四倍的時間。**真的有哪一顆出來覺得糊，那一顆單獨用 20 步重跑就好——每顆是獨立生成，沒有綁定成本。</p><p><strong>如果只能帶走一句</strong>：不是「8 步很好用」，是</p><blockquote><p>你量到的第一個數字，通常包含一個你沒注意到的東西。</p></blockquote><p>這篇裡我犯了四次：<strong>首次載入</strong>算進生成時間、用<strong>被自己縮放污染</strong>的圖去比畫質、 <strong>跨機器</strong>除出一個 5.4 倍、然後拿那個錯的數字去<strong>否定一個對的數字</strong>。 再往前一篇，是我把別的工作排進同一張卡。</p><p>五次錯誤，五種不同的污染源，而每一次的當下我都覺得數字很合理。</p><p><strong>自架真正買到的，是這些錯誤會當場現形。</strong> 在 API 那一端，你只會拿到一個數字，而且沒有機會知道它是怎麼來的。</p><hr><p><em>本文的測試環境：<a href="https://runpod.io?ref=s3bs0r0v" target="_blank" rel="noreferrer">RunPod</a> 租用之 GPU，MiniMax H3 剪枝 INT8 開源權重，於 ComfyUI 部署，Ref2VA 模式，輸出 768 × 1376。 加速使用 alibaba-pai 官方 PDD 蒸餾 LoRA（<code>MiniMax-H3-Ref2VA-Acc-8Step</code>）， 搭配 <a href="https://github.com/Jalen-Brunson/ComfyUI-MiniMax-H3-PDD-Acc" target="_blank" rel="noreferrer">ComfyUI-MiniMax-H3-PDD-Acc</a> 節點包， euler ／ sigma shift 12.0 ／ 3.0 ／ nfe 8 ／ CFG 1.0。計時為 2026-09-02。</em></p><p><em>成本的完整比較見<a href="./ai-video-cost-selfhost">〈那張 AI 影片比價表，少了一列〉</a>。</em></p><p><em>本文的 RunPod 連結為推薦連結，透過它註冊我會獲得少量回饋，不影響你的價格。</em></p><p><em><a href="https://aidream.com.tw" target="_blank" rel="noreferrer">aidream.com.tw</a></em></p>`,134)])])}const k=a(t,[["render",i]]);export{g as __pageData,k as default};
